import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第五十八卦 兌 兌為澤 兌上兌下","description":"周易 - 第五十八卦 兌 兌為澤 兌上兌下","frontmatter":{"title":"第五十八卦 兌 兌為澤 兌上兌下","description":"周易 - 第五十八卦 兌 兌為澤 兌上兌下"},"headers":[],"relativePath":"classics/zhouyi/059.md","filePath":"classics/zhouyi/059.md"}'),l={name:"classics/zhouyi/059.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="兌" tabindex="-1">兌 <a class="header-anchor" href="#兌" aria-label="Permalink to “兌”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨，利貞。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>兌，說也。剛中而柔外，說以利貞，是以順乎天，而應乎人。說以先民，民忘其勞；說以犯難，民忘其死；說之大，民勸矣哉！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>麗澤，兌；君子以朋友講習。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>和兌，吉。象曰：和兌之吉，行未疑也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>孚兌，吉，悔亡。象曰：孚兌之吉，信志也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>來兌，兇。象曰：來兌之兇，位不當也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>商兌，未寧，介疾有喜。象曰：九四之喜，有慶也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>孚於剝，有厲。象曰：孚於剝，位正當也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>引兌。象曰：上六引兌，未光也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
